sap.ui.define([], function () {
  "use strict";
  return {
    // list report controller extension
    onListNavigationExtension: function (event) {
      const context = event.getSource().getBindingContext();
      const customerId = context.getProperty("CustomerID");
      // "CustomerDisplay" is an outbound defined in sap.app/crossNavigation/outbounds
      this.extensionAPI.getNavigationController().navigateExternal("CustomerDisplay", {
        CustomerID: customerId
      });
      return true; // the standard navigation is not performed
    }
  };
});
